def choose_move(observation):
    width = observation.get('width', 0)
    height = observation.get('height', 0)
    own_pos = observation.get('players', {}).get('own', {}).get('pos', [0, 0])
    resources = observation.get('resources', [])
    enemies = observation.get('players', {}).get('enemies', [])
    territory = observation.get('territory', {}).get('owner', [])

    x, y = own_pos

    # Helper function to determine move direction towards target
    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > x:
            dx = 1
        elif target_x < x:
            dx = -1
        if target_y > y:
            dy = 1
        elif target_y < y:
            dy = -1
        return [dx, dy]

    # 1. Resource collection
    for r in resources:
        rx, ry = r
        dist = abs(rx - x) + abs(ry - y)
        if dist == 1:
            return [rx - x, ry - y]
        if dist > 1:
            return move_towards(rx, ry)

    # 2. Pursuit or evasion
    for enemy in enemies:
        ex, ey = enemy.get('pos', [0, 0])
        dist = abs(ex - x) + abs(ey - y)
        if dist == 1:
            return [ex - x, ey - y]
        if dist > 1:
            return move_towards(ex, ey)

    # 3. Territory control
    for idx, owner in enumerate(territory):
        if owner != 'own':
            tx = idx % width
            ty = idx // width
            dist = abs(tx - x) + abs(ty - y)
            if dist == 1:
                return [tx - x, ty - y]
            if dist > 1:
                return move_towards(tx, ty)

    # 4. Default: stay still
    return [0, 0]

